{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.FACT_PARETO_SLAB_PERFORMANCE AS WITH DATE_PARAMS_GENERATOR AS ( SELECT SEQ.MONTH_OFFSET, TO_CHAR(DATEADD(\'MONTH\', -SEQ.MONTH_OFFSET, DATE_TRUNC(\'MONTH\', CURRENT_DATE())), \'YYYY-MM\') AS REPORT_MONTH, TO_CHAR(DATEADD(\'MONTH\', -SEQ.MONTH_OFFSET, DATE_TRUNC(\'MONTH\', CURRENT_DATE())), \'Mon YYYY\') AS MONTH_LABEL, DATEADD(\'MONTH\', -SEQ.MONTH_OFFSET, DATE_TRUNC(\'MONTH\', CURRENT_DATE())) AS START_DATE, CASE WHEN SEQ.MONTH_OFFSET = 0 THEN CURRENT_DATE() ELSE LAST_DAY(DATEADD(\'MONTH\', -SEQ.MONTH_OFFSET, DATE_TRUNC(\'MONTH\', CURRENT_DATE()))) END AS END_DATE FROM ( SELECT 0 AS MONTH_OFFSET UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 ) SEQ ), LATEST_INV_DATES AS ( SELECT P.REPORT_MONTH, P.MONTH_LABEL, P.START_DATE, P.END_DATE, COALESCE(MAX(I.DATE), P.END_DATE) AS MAX_INV_DATE FROM DATE_PARAMS_GENERATOR P LEFT JOIN SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I ON I.DATE <= P.END_DATE GROUP BY P.REPORT_MONTH, P.MONTH_LABEL, P.START_DATE, P.END_DATE, P.MONTH_OFFSET ), SKU_CATALOG_PRICES AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, AVG(CAST(PRICE AS NUMBER(10,2))) AS CATALOG_MRP FROM SNITCH_DB.MAPLEMONK.AVAILABILITY_MASTER_V2 WHERE PRICE IS NOT NULL AND PRICE > 0 GROUP BY REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') ), SKU_SALES_PRICES AS ( SELECT REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') AS CLEAN_SKU_GROUP, AVG(CAST(COALESCE(SELLING_PRICE, MRP) AS NUMBER(10,2))) AS HISTORICAL_PRICE FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE WHERE COALESCE(SELLING_PRICE, MRP) > 0 GROUP BY REGEXP_REPLACE(UPPER(TRIM(SKU_GROUP)), \'[^A-Z0-9]\', \'\') ), SKU_MASTER_PRICES AS ( SELECT COALESCE(C.CLEAN_SKU_GROUP, S.CLEAN_SKU_GROUP) AS CLEAN_SKU_GROUP, COALESCE(C.CATALOG_MRP, S.HISTORICAL_PRICE) AS SKU_PRICE FROM SKU_CATALOG_PRICES C FULL OUTER JOIN SKU_SALES_PRICES S ON C.CLEAN_SKU_GROUP = S.CLEAN_SKU_GROUP ), CATEGORY_AVG_PRICES AS ( SELECT CASE WHEN UPPER(TRIM(NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(NEW_CATEGORY)) END AS CATEGORY, AVG(P.SKU_PRICE) AS CAT_DEFAULT_PRICE FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I INNER JOIN SKU_MASTER_PRICES P ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = P.CLEAN_SKU_GROUP GROUP BY CASE WHEN UPPER(TRIM(NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(NEW_CATEGORY)) END ), INV_SLABS AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', I.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'UNMAPPED_CLUSTER\') AS CLUSTER_NAME, CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(I.NEW_CATEGORY)) END AS CATEGORY, R.PRICE_SLAB_CODE, R.PRICE_RANGE_LABEL, (COALESCE(I.INVENTORY, 0) + COALESCE(I.JIT_QTY, 0)) AS INV_UNITS_CLOSING FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I INNER JOIN LATEST_INV_DATES L ON I.DATE = L.MAX_INV_DATE LEFT JOIN SKU_MASTER_PRICES P ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = P.CLEAN_SKU_GROUP LEFT JOIN CATEGORY_AVG_PRICES CA ON ( CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(I.NEW_CATEGORY)) END ) = CA.CATEGORY INNER JOIN SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS R ON ( CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(I.NEW_CATEGORY)) END ) = R.CATEGORY AND COALESCE(P.SKU_PRICE, CA.CAT_DEFAULT_PRICE, 1200) >= R.SLAB_MIN_PRICE AND COALESCE(P.SKU_PRICE, CA.CAT_DEFAULT_PRICE, 1200) <= R.SLAB_MAX_PRICE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(I.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE CAST(I.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') ), OPENING_INV_SLABS AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, I.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', I.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'UNMAPPED_CLUSTER\') AS CLUSTER_NAME, CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(I.NEW_CATEGORY)) END AS CATEGORY, R.PRICE_SLAB_CODE, R.PRICE_RANGE_LABEL, (COALESCE(I.INVENTORY, 0) + COALESCE(I.JIT_QTY, 0)) AS INV_UNITS_OPENING FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 I INNER JOIN LATEST_INV_DATES L ON I.DATE = L.START_DATE LEFT JOIN SKU_MASTER_PRICES PC ON REGEXP_REPLACE(UPPER(TRIM(I.SKU_GROUP)), \'[^A-Z0-9]\', \'\') = PC.CLEAN_SKU_GROUP LEFT JOIN CATEGORY_AVG_PRICES CA ON ( CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(I.NEW_CATEGORY)) END ) = CA.CATEGORY INNER JOIN SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS R ON ( CASE WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(I.NEW_CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(I.NEW_CATEGORY)) END ) = R.CATEGORY AND COALESCE(PC.SKU_PRICE, CA.CAT_DEFAULT_PRICE, 1200) >= R.SLAB_MIN_PRICE AND COALESCE(PC.SKU_PRICE, CA.CAT_DEFAULT_PRICE, 1200) <= R.SLAB_MAX_PRICE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(I.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE CAST(I.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') ), SALES_SLABS AS ( SELECT L.REPORT_MONTH, L.MONTH_LABEL, S.BRANCH_CODE, COALESCE(M.STORE_NAME, CONCAT(\'STORE_\', S.BRANCH_CODE)) AS STORE_NAME, COALESCE(M.CLUSTER_NAME, \'UNMAPPED_CLUSTER\') AS CLUSTER_NAME, CASE WHEN UPPER(TRIM(S.CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(S.CATEGORY)) END AS CATEGORY, S.SHIPPING_QUANTITY AS QUANTITY, (S.SHIPPING_QUANTITY * S.SELLING_PRICE) AS REVENUE, R.PRICE_SLAB_CODE, R.PRICE_RANGE_LABEL FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE S INNER JOIN LATEST_INV_DATES L ON S.ORDER_DATE >= L.START_DATE AND S.ORDER_DATE <= L.END_DATE INNER JOIN SNITCH_DB.MAPLEMONK.REF_CATEGORY_PRICE_SLABS R ON ( CASE WHEN UPPER(TRIM(S.CATEGORY)) IN (\'CHINO\', \'CHINOS\', \'TROUSER\', \'TROUSERS\') THEN \'TROUSERS\' WHEN UPPER(TRIM(S.CATEGORY)) IN (\'DENIM\', \'DENIMS\', \'DEMIN\', \'DEMINS\', \'JEAN\', \'JEANS\') THEN \'JEANS\' ELSE UPPER(TRIM(S.CATEGORY)) END ) = R.CATEGORY AND COALESCE(S.SELLING_PRICE, S.MRP) >= R.SLAB_MIN_PRICE AND COALESCE(S.SELLING_PRICE, S.MRP) <= R.SLAB_MAX_PRICE LEFT JOIN SNITCH_DB.MAPLEMONK.STORE_ZONE_MAP M ON CAST(S.BRANCH_CODE AS VARCHAR) = CAST(M.BRANCH_CODE AS VARCHAR) WHERE LOWER(S.ORDER_STATUS) LIKE \'%process%\' AND S.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') AND CAST(S.BRANCH_CODE AS VARCHAR) NOT IN (\'2\',\'8\',\'9\',\'10\',\'32\',\'33\',\'35\',\'45\',\'46\',\'59\',\'60\',\'74\',\'76\',\'78\',\'93\',\'94\') ), COMBINED_METRICS AS ( SELECT REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, 0 AS INV_UNITS_CLOSING, 0 AS INV_UNITS_OPENING, QUANTITY AS SALES_QTY, REVENUE FROM SALES_SLABS UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, INV_UNITS_CLOSING, 0 AS INV_UNITS_OPENING, 0 AS SALES_QTY, 0 AS REVENUE FROM INV_SLABS UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CLUSTER_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, 0 AS INV_UNITS_CLOSING, INV_UNITS_OPENING, 0 AS SALES_QTY, 0 AS REVENUE FROM OPENING_INV_SLABS ), UNIFIED_AGGREGATE AS ( SELECT REPORT_MONTH, MONTH_LABEL, \'1. Company Wide\' AS HIERARCHY_LEVEL, \'ALL STORES\' AS LOCATION_ID, \'National (All Stores)\' AS LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(INV_UNITS_CLOSING) AS STORE_INV_UNITS_CLOSING, SUM(INV_UNITS_OPENING) AS STORE_INV_UNITS_OPENING, SUM(SALES_QTY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM COMBINED_METRICS GROUP BY REPORT_MONTH, MONTH_LABEL, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, \'2. Cluster Wise\' AS HIERARCHY_LEVEL, CLUSTER_NAME AS LOCATION_ID, CONCAT(CLUSTER_NAME, \' Cluster\') AS LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(INV_UNITS_CLOSING) AS STORE_INV_UNITS_CLOSING, SUM(INV_UNITS_OPENING) AS STORE_INV_UNITS_OPENING, SUM(SALES_QTY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM COMBINED_METRICS GROUP BY REPORT_MONTH, MONTH_LABEL, CLUSTER_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL UNION ALL SELECT REPORT_MONTH, MONTH_LABEL, \'3. Store Wise\' AS HIERARCHY_LEVEL, CAST(BRANCH_CODE AS VARCHAR) AS LOCATION_ID, STORE_NAME AS LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, SUM(INV_UNITS_CLOSING) AS STORE_INV_UNITS_CLOSING, SUM(INV_UNITS_OPENING) AS STORE_INV_UNITS_OPENING, SUM(SALES_QTY) AS SALES_UNITS, SUM(REVENUE) AS SALES_REVENUE FROM COMBINED_METRICS GROUP BY REPORT_MONTH, MONTH_LABEL, BRANCH_CODE, STORE_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL ), PARETO_CALC AS ( SELECT REPORT_MONTH, MONTH_LABEL, HIERARCHY_LEVEL, LOCATION_ID, LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, STORE_INV_UNITS_CLOSING, STORE_INV_UNITS_OPENING, ROUND(100.0 * STORE_INV_UNITS_CLOSING / NULLIF(SUM(STORE_INV_UNITS_CLOSING) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY), 0), 2) AS INV_SHARE_PCT, SALES_UNITS, SALES_REVENUE, ROUND(100.0 * SALES_UNITS / NULLIF(SUM(SALES_UNITS) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY), 0), 2) AS SALES_SHARE_PCT, SUM(SALES_UNITS) OVER ( PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY ORDER BY SALES_UNITS DESC, PRICE_SLAB_CODE ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) / NULLIF(SUM(SALES_UNITS) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY), 0) AS CUMULATIVE_SHARE, ROUND(SALES_UNITS / NULLIF(SALES_UNITS + STORE_INV_UNITS_CLOSING, 0), 4) AS STR1, ROUND(SALES_UNITS / NULLIF((STORE_INV_UNITS_OPENING + STORE_INV_UNITS_CLOSING) / 2.0, 0), 4) AS STR2, ROUND(SALES_UNITS / NULLIF(STORE_INV_UNITS_OPENING, 0), 4) AS STR3 FROM UNIFIED_AGGREGATE ), STR3_PARETO_CALC AS ( SELECT *, SUM(COALESCE(STR3, 0)) OVER ( PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY ORDER BY COALESCE(STR3, 0) DESC, PRICE_SLAB_CODE ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) / NULLIF(SUM(COALESCE(STR3, 0)) OVER (PARTITION BY REPORT_MONTH, HIERARCHY_LEVEL, LOCATION_ID, CATEGORY), 0) AS CUMULATIVE_STR3_SHARE FROM PARETO_CALC ) SELECT REPORT_MONTH, MONTH_LABEL, HIERARCHY_LEVEL, LOCATION_ID, LOCATION_NAME, CATEGORY, PRICE_SLAB_CODE, PRICE_RANGE_LABEL, STORE_INV_UNITS_CLOSING, INV_SHARE_PCT, SALES_UNITS, SALES_REVENUE, SALES_SHARE_PCT, ROUND(CUMULATIVE_SHARE * 100, 2) AS CUMULATIVE_SALES_SHARE_PCT, CASE WHEN CUMULATIVE_SHARE <= 0.50 THEN \'A\' WHEN CUMULATIVE_SHARE <= 0.80 THEN \'B\' WHEN CUMULATIVE_SHARE <= 0.95 THEN \'C\' ELSE \'D\' END AS PARETO_ABCD_RANK, STORE_INV_UNITS_OPENING, STR1, STR2, STR3, ROUND(CUMULATIVE_STR3_SHARE * 100, 2) AS CUMULATIVE_STR3_SHARE_PCT, CASE WHEN CUMULATIVE_STR3_SHARE <= 0.50 THEN \'A\' WHEN CUMULATIVE_STR3_SHARE <= 0.80 THEN \'B\' WHEN CUMULATIVE_STR3_SHARE <= 0.95 THEN \'C\' ELSE \'D\' END AS STR3_PARETO_ABCD_RANK, CURRENT_TIMESTAMP() AS UPDATED_AT FROM STR3_PARETO_CALC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            